cat > src/main.rs <<'EOF'
use std::f64::consts::PI;
#[derive(Clone,Copy,Debug)]
struct Lab{l:f64,a:f64,b:f64}
fn lin(c:f64)->f64{ if c<=0.04045 {c/12.92} else {((c+0.055)/1.055).powf(2.4)} }
fn lab(rgb:(u8,u8,u8))->Lab{
    let r=lin(rgb.0 as f64/255.0); let g=lin(rgb.1 as f64/255.0); let b=lin(rgb.2 as f64/255.0);
    let x=0.4124*r+0.3576*g+0.1805*b;
    let y=0.2126*r+0.7152*g+0.0722*b;
    let z=0.0193*r+0.1192*g+0.9505*b;
    let cut=(6.0f64/29.0).powi(3);
    let f=|t:f64| if t>cut {t.cbrt()} else {t/(3.0*(6.0f64/29.0).powi(2))+4.0/29.0};
    let fx=f(x/0.95047); let fy=f(y); let fz=f(z/1.08883);
    Lab{l:116.0*fy-16.0,a:500.0*(fx-fy),b:200.0*(fy-fz)}
}
fn de2000(c1:Lab,c2:Lab, variant:u32)->f64{
    let (l1,a1,b1)=(c1.l,c1.a,c1.b); let (l2,a2,b2)=(c2.l,c2.a,c2.b);
    let c1s=(a1*a1+b1*b1).sqrt(); let c2s=(a2*a2+b2*b2).sqrt();
    let cb=(c1s+c2s)/2.0;
    let g=0.5*(1.0-(cb.powi(7)/(cb.powi(7)+25f64.powi(7))).sqrt());
    let a1p=(1.0+g)*a1; let a2p=(1.0+g)*a2;
    let c1p=(a1p*a1p+b1*b1).sqrt(); let c2p=(a2p*a2p+b2*b2).sqrt();
    let hp=|b:f64,a:f64| { if b==0.0 && a==0.0 {0.0} else { let h=b.atan2(a).to_degrees(); if h<0.0 {h+360.0} else {h} } };
    let h1p=hp(b1,a1p); let h2p=hp(b2,a2p);
    let dlp=l2-l1; let dcp=c2p-c1p;
    let dhp = if c1p*c2p==0.0 {0.0} else { let d=h2p-h1p; if d>180.0 {d-360.0} else if d< -180.0 {d+360.0} else {d} };
    let dHp=2.0*(c1p*c2p).sqrt()*(dhp.to_radians()/2.0).sin();
    let lbp=(l1+l2)/2.0; let cbp=(c1p+c2p)/2.0;
    let hbp = if c1p*c2p==0.0 {h1p+h2p} else if (h1p-h2p).abs()<=180.0 {(h1p+h2p)/2.0} else if h1p+h2p<360.0 {(h1p+h2p+360.0)/2.0} else {(h1p+h2p-360.0)/2.0};
    let t=1.0-0.17*(hbp-30.0).to_radians().cos()+0.24*(2.0*hbp).to_radians().cos()+0.32*(3.0*hbp+6.0).to_radians().cos()-0.20*(4.0*hbp-63.0).to_radians().cos();
    let dtheta=30.0*(-((hbp-275.0)/25.0).powi(2)).exp();
    let rc=2.0*(cbp.powi(7)/(cbp.powi(7)+25f64.powi(7))).sqrt();
    let sl=1.0+0.015*(lbp-50.0).powi(2)/(20.0+(lbp-50.0).powi(2)).sqrt();
    let sc=1.0+0.045*cbp; let sh=1.0+0.015*cbp*t;
    let rt=-(2.0*dtheta).to_radians().sin()*rc;
    let _=variant; let _=PI;
    ((dlp/sl).powi(2)+(dcp/sc).powi(2)+(dHp/sh).powi(2)+rt*(dcp/sc)*(dHp/sh)).sqrt()
}
fn de76(c1:Lab,c2:Lab)->f64{ ((c1.l-c2.l).powi(2)+(c1.a-c2.a).powi(2)+(c1.b-c2.b).powi(2)).sqrt() }
fn pal(i:usize)->(u8,u8,u8){
    let lv=[0u8,95,135,175,215,255];
    if i>=232 { let v=(8+10*(i-232)) as u8; (v,v,v) } else { let j=i-16; (lv[j/36],lv[(j/6)%6],lv[j%6]) }
}
fn main(){
    let table=std::fs::read("/tmp/a8/table.bin").unwrap();
    let args:Vec<String>=std::env::args().collect();
    let step:usize=args.get(1).map(|s|s.parse().unwrap()).unwrap_or(97);
    let palette:Vec<(usize,Lab)>=(16..256).map(|i|(i,lab(pal(i)))).collect();
    let metrics:Vec<(&str,Box<dyn Fn(Lab,Lab)->f64>)>=vec![
        ("de76",Box::new(|a,b|de76(a,b))),
        ("de2000(in,pal)",Box::new(|a,b|de2000(a,b,0))),
        ("de2000(pal,in)",Box::new(|a,b|de2000(b,a,0))),
    ];
    for (name,m) in metrics.iter(){
        for (lo,hi) in [(16usize,256usize),(16,255)] {
        let mut ok=0; let mut tot=0; let mut bad=vec![];
        let mut idx=0;
        while idx<table.len(){
            let rgb=((idx>>16) as u8,((idx>>8)&255) as u8,(idx&255) as u8);
            let l=lab(rgb);
            let mut best=0; let mut bd=f64::INFINITY;
            for (i,p) in palette.iter(){ if *i<lo||*i>=hi {continue}; let d=m(l,*p); if d<bd {bd=d;best=*i;} }
            tot+=1; if best==table[idx] as usize {ok+=1} else if bad.len()<5 {bad.push((rgb,table[idx],best))}
            idx+=step;
        }
        println!("{} {}..{}: {}/{} {:?}",name,lo,hi,ok,tot,bad);
        }
    }
}
EOF
