    pub a: f64,
    pub b: f64,
    pub alpha: f64,
}

#[derive(Clone, Copy, Debug)]
pub struct OkLch {
    pub l: f64,
    pub c: f64,
    pub h: f64,
    pub alpha: f64,
}

#[derive(Clone, Copy, Debug)]
pub struct Hsva {
    pub h: f64,
    pub s: f64,
    pub v: f64,
    pub alpha: f64,
}

#[derive(Clone, Copy, Debug)]
pub struct Cmyk {
    pub c: f64,
    pub m: f64,
    pub y: f64,
    pub k: f64,
}

// D65 reference white
const XN: f64 = 0.950_47;
const YN: f64 = 1.0;
const ZN: f64 = 1.088_83;

fn srgb_to_linear(c: f64) -> f64 {
    if c <= 0.04045 {
        c / 12.92
    } else {
        ((c + 0.055) / 1.055).powf(2.4)
    }
}

fn linear_to_srgb(c: f64) -> f64 {
    if c <= 0.003_130_8 {
        12.92 * c
    } else {
        1.055 * c.powf(1.0 / 2.4) - 0.055
    }
}

fn lab_f(t: f64) -> f64 {
    let delta: f64 = 6.0 / 29.0;
    if t > delta * delta * delta {
        t.cbrt()
    } else {
        t / (3.0 * delta * delta) + 4.0 / 29.0
    }
}

fn lab_f_inv(t: f64) -> f64 {
    let delta: f64 = 6.0 / 29.0;
    if t > delta {
        t * t * t
    } else {
        3.0 * delta * delta * (t - 4.0 / 29.0)
    }
}

impl Color {
    pub fn from_hsla(hue: f64, saturation: f64, lightness: f64, alpha: f64) -> Color {
        Color {
            hue: normalize_hue(hue),
            saturation: clamp(0.0, 1.0, saturation),
            lightness: clamp(0.0, 1.0, lightness),
            alpha: clamp(0.0, 1.0, alpha),
        }
    }

    pub fn from_hsl(hue: f64, saturation: f64, lightness: f64) -> Color {
        Self::from_hsla(hue, saturation, lightness, 1.0)
    }

    pub fn from_rgba(r: u8, g: u8, b: u8, alpha: f64) -> Color {
        Self::from_rgba_float(
            r as f64 / 255.0,
            g as f64 / 255.0,
            b as f64 / 255.0,
            alpha,
        )
    }

    pub fn from_rgb(r: u8, g: u8, b: u8) -> Color {
        Self::from_rgba(r, g, b, 1.0)
    }

    pub fn from_rgba_float(r: f64, g: f64, b: f64, alpha: f64) -> Color {
        let r = clamp(0.0, 1.0, r);
        let g = clamp(0.0, 1.0, g);
        let b = clamp(0.0, 1.0, b);

        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let chroma = max - min;

        let hue = if chroma == 0.0 {
            0.0
        } else if max == r {
            60.0 * (((g - b) / chroma) % 6.0)
        } else if max == g {
            60.0 * ((b - r) / chroma + 2.0)
        } else {
            60.0 * ((r - g) / chroma + 4.0)
        };

        let lightness = (max + min) / 2.0;
        let saturation = if chroma == 0.0 {
            0.0
        } else {
            chroma / (1.0 - (2.0 * lightness - 1.0).abs())
        };

        Self::from_hsla(hue, saturation, lightness, alpha)
    }

    pub fn from_rgb_float(r: f64, g: f64, b: f64) -> Color {
        Self::from_rgba_float(r, g, b, 1.0)
    }

    pub fn from_hsva(h: f64, s: f64, v: f64, alpha: f64) -> Color {
        let s = clamp(0.0, 1.0, s);
        let v = clamp(0.0, 1.0, v);
        let l = v * (1.0 - s / 2.0);
        let sl = if l == 0.0 || l == 1.0 {
            0.0
        } else {
            (v - l) / l.min(1.0 - l)
        };
        Self::from_hsla(h, sl, l, alpha)
    }

    pub fn from_xyz(x: f64, y: f64, z: f64, alpha: f64) -> Color {
        let r = 3.2406 * x - 1.5372 * y - 0.4986 * z;
        let g = -0.9689 * x + 1.8758 * y + 0.0415 * z;
        let b = 0.0557 * x - 0.2040 * y + 1.0570 * z;
        Self::from_rgba_float(linear_to_srgb(r), linear_to_srgb(g), linear_to_srgb(b), alpha)
    }

    pub fn from_lab(l: f64, a: f64, b: f64, alpha: f64) -> Color {
        let fy = (l + 16.0) / 116.0;
        let fx = fy + a / 500.0;
        let fz = fy - b / 200.0;
        let x = XN * lab_f_inv(fx);
        let y = YN * lab_f_inv(fy);
        let z = ZN * lab_f_inv(fz);
        Self::from_xyz(x, y, z, alpha)
    }

    pub fn from_lch(l: f64, c: f64, h: f64, alpha: f64) -> Color {
        let hr = h * PI / 180.0;
        Self::from_lab(l, c * hr.cos(), c * hr.sin(), alpha)
    }

    pub fn from_oklab(l: f64, a: f64, b: f64, alpha: f64) -> Color {
        let l_ = l + 0.396_337_777_4 * a + 0.215_803_757_3 * b;
        let m_ = l - 0.105_561_345_8 * a - 0.063_854_172_8 * b;
        let s_ = l - 0.089_484_177_5 * a - 1.291_485_548_0 * b;

        let l3 = l_ * l_ * l_;
        let m3 = m_ * m_ * m_;
        let s3 = s_ * s_ * s_;

        let r = 4.076_741_662_1 * l3 - 3.307_711_591_3 * m3 + 0.230_969_929_2 * s3;
        let g = -1.268_438_004_6 * l3 + 2.609_757_401_1 * m3 - 0.341_319_396_5 * s3;
        let bl = -0.004_196_086_3 * l3 - 0.703_418_614_7 * m3 + 1.707_614_701_0 * s3;

        Self::from_rgba_float(linear_to_srgb(r), linear_to_srgb(g), linear_to_srgb(bl), alpha)
    }

    pub fn from_oklch(l: f64, c: f64, h: f64, alpha: f64) -> Color {
        let hr = h * PI / 180.0;
        Self::from_oklab(l, c * hr.cos(), c * hr.sin(), alpha)
    }

    pub fn graytone(lightness: f64) -> Color {
        Self::from_hsl(0.0, 0.0, lightness)
    }

    pub fn black() -> Color {
        Self::from_hsl(0.0, 0.0, 0.0)
    }

    pub fn white() -> Color {
        Self::from_hsl(0.0, 0.0, 1.0)
    }

    pub fn red() -> Color {
        Self::from_rgb(255, 0, 0)
    }

    pub fn yellow() -> Color {
        Self::from_rgb(255, 255, 0)
    }

    // ------------------------------------------------------------------
    // Conversions

    pub fn to_rgba_float(&self) -> Rgba {
        let h = self.hue;
        let s = self.saturation;
        let l = self.lightness;

        let c = (1.0 - (2.0 * l - 1.0).abs()) * s;
        let h_ = h / 60.0;
        let x = c * (1.0 - (h_ % 2.0 - 1.0).abs());
        let m = l - c / 2.0;

        let (r, g, b) = if (0.0..1.0).contains(&h_) {
            (c, x, 0.0)
        } else if (1.0..2.0).contains(&h_) {
            (x, c, 0.0)
        } else if (2.0..3.0).contains(&h_) {
            (0.0, c, x)
        } else if (3.0..4.0).contains(&h_) {
            (0.0, x, c)
        } else if (4.0..5.0).contains(&h_) {
            (x, 0.0, c)
        } else {
            (c, 0.0, x)
        };

        Rgba {
            r: r + m,
            g: g + m,
            b: b + m,
            alpha: self.alpha,
        }
    }

    pub fn to_rgba(&self) -> Rgba8 {
        let c = self.to_rgba_float();
        let conv = |v: f64| (255.0 * v).round() as u8;
        Rgba8 {
            r: conv(c.r),
            g: conv(c.g),
            b: conv(c.b),
            alpha: self.alpha,
        }
    }

    pub fn to_hsva(&self) -> Hsva {
        let l = self.lightness;
        let s = self.saturation;
        let v = l + s * l.min(1.0 - l);
        let sv = if v == 0.0 { 0.0 } else { 2.0 * (1.0 - l / v) };
        Hsva {
            h: self.hue,
            s: sv,
            v,
            alpha: self.alpha,
        }
    }

    pub fn to_xyz(&self) -> Xyz {
        let c = self.to_rgba_float();
        let r = srgb_to_linear(c.r);
        let g = srgb_to_linear(c.g);
        let b = srgb_to_linear(c.b);
        Xyz {
            x: 0.4124 * r + 0.3576 * g + 0.1805 * b,
            y: 0.2126 * r + 0.7152 * g + 0.0722 * b,
            z: 0.0193 * r + 0.1192 * g + 0.9505 * b,
            alpha: self.alpha,
        }
    }

    pub fn to_lab(&self) -> Lab {
        let xyz = self.to_xyz();
        let fx = lab_f(xyz.x / XN);
        let fy = lab_f(xyz.y / YN);
        let fz = lab_f(xyz.z / ZN);
        Lab {
            l: 116.0 * fy - 16.0,
            a: 500.0 * (fx - fy),
            b: 200.0 * (fy - fz),
            alpha: self.alpha,
        }
    }

    pub fn to_lch(&self) -> Lch {
        let lab = self.to_lab();
        let c = (lab.a * lab.a + lab.b * lab.b).sqrt();
        let h = normalize_hue(lab.b.atan2(lab.a) * 180.0 / PI);
        Lch {
            l: lab.l,
            c,
            h,
            alpha: self.alpha,
        }
    }

    pub fn to_oklab(&self) -> OkLab {
        let c = self.to_rgba_float();
        let r = srgb_to_linear(c.r);
        let g = srgb_to_linear(c.g);
        let b = srgb_to_linear(c.b);

        let l = 0.412_221_470_8 * r + 0.536_332_536_3 * g + 0.051_445_992_9 * b;
        let m = 0.211_903_498_2 * r + 0.680_699_545_1 * g + 0.107_396_956_6 * b;
        let s = 0.088_302_461_9 * r + 0.281_718_837_6 * g + 0.629_978_700_5 * b;

        let l_ = l.cbrt();
        let m_ = m.cbrt();
        let s_ = s.cbrt();

        OkLab {
            l: 0.210_454_255_3 * l_ + 0.793_617_785_0 * m_ - 0.004_072_046_8 * s_,
            a: 1.977_998_495_1 * l_ - 2.428_592_205_0 * m_ + 0.450_593_709_9 * s_,
            b: 0.025_904_037_1 * l_ + 0.782_771_766_2 * m_ - 0.808_675_766_0 * s_,
            alpha: self.alpha,
        }
    }

    pub fn to_oklch(&self) -> OkLch {
        let lab = self.to_oklab();
        let c = (lab.a * lab.a + lab.b * lab.b).sqrt();
        let h = normalize_hue(lab.b.atan2(lab.a) * 180.0 / PI);
        OkLch {
            l: lab.l,
            c,
            h,
            alpha: self.alpha,
        }
    }

    pub fn to_cmyk(&self) -> Cmyk {
        let rgba = self.to_rgba();
        let r = rgba.r as f64 / 255.0;
        let g = rgba.g as f64 / 255.0;
        let b = rgba.b as f64 / 255.0;
        let k = 1.0 - r.max(g).max(b);
        let (c, m, y) = if k == 1.0 {
            (0.0, 0.0, 0.0)
        } else {
            (
                (1.0 - r - k) / (1.0 - k),
                (1.0 - g - k) / (1.0 - k),
                (1.0 - b - k) / (1.0 - k),
            )
        };
        Cmyk { c, m, y, k }
    }

    /// Relative luminance (WCAG definition).
    pub fn luminance(&self) -> f64 {
        let c = self.to_rgba_float();
        let r = srgb_to_linear(c.r);
        let g = srgb_to_linear(c.g);
        let b = srgb_to_linear(c.b);
        0.2126 * r + 0.7152 * g + 0.0722 * b
    }

    /// Perceived brightness (W3C definition).
    pub fn brightness(&self) -> f64 {
        let c = self.to_rgba_float();
        (299.0 * c.r + 587.0 * c.g + 114.0 * c.b) / 1000.0
    }

    pub fn contrast_ratio(&self, other: &Color) -> f64 {
        let l1 = self.luminance();
        let l2 = other.luminance();
        if l1 > l2 {
            (l1 + 0.05) / (l2 + 0.05)
        } else {
            (l2 + 0.05) / (l1 + 0.05)
        }
    }

    pub fn text_color(&self) -> Color {
        if self.luminance() > 0.179 {
            Color::black()
        } else {
            Color::white()
        }
    }

    // ------------------------------------------------------------------
    // Modifications

    pub fn rotate_hue(&self, delta: f64) -> Color {
        Self::from_hsla(self.hue + delta, self.saturation, self.lightness, self.alpha)
    }

    pub fn complementary(&self) -> Color {
        self.rotate_hue(180.0)
    }

    pub fn lighten(&self, f: f64) -> Color {
        Self::from_hsla(self.hue, self.saturation, self.lightness + f, self.alpha)
    }

    pub fn darken(&self, f: f64) -> Color {
        self.lighten(-f)
    }

    pub fn saturate(&self, f: f64) -> Color {
        Self::from_hsla(self.hue, self.saturation + f, self.lightness, self.alpha)
    }

    pub fn desaturate(&self, f: f64) -> Color {
        self.saturate(-f)
    }

    pub fn to_gray(&self) -> Color {
        let lum = self.luminance();
        let l = linear_to_srgb(lum);
        Self::from_hsla(self.hue, 0.0, l, 1.0)
    }

    pub fn with_alpha(&self, alpha: f64) -> Color {
        Self::from_hsla(self.hue, self.saturation, self.lightness, alpha)
    }

    /// Alpha-composite this color over the given (opaque) background.
    pub fn composite(&self, background: &Color) -> Color {
        let a = self.alpha;
        if a >= 1.0 {
            return *self;
        }
        let fg = self.to_rgba_float();
        let bg = background.to_rgba_float();
        Color::from_rgb_float(
            fg.r * a + bg.r * (1.0 - a),
            fg.g * a + bg.g * (1.0 - a),
            fg.b * a + bg.b * (1.0 - a),
        )
    }

    // ------------------------------------------------------------------
    // Distances

    pub fn distance_delta_e_cie76(&self, other: &Color) -> f64 {
        let a = self.to_lab();
        let b = other.to_lab();
        ((a.l - b.l).powi(2) + (a.a - b.a).powi(2) + (a.b - b.b).powi(2)).sqrt()
    }

    pub fn distance_delta_e_ciede2000(&self, other: &Color) -> f64 {
        ciede2000(&self.to_lab(), &other.to_lab())
    }
}

impl PartialEq for Color {
    fn eq(&self, other: &Color) -> bool {
        self.to_rgba() == other.to_rgba()
    }
}

pub fn ciede2000(c1: &Lab, c2: &Lab) -> f64 {
    let (l1, a1, b1) = (c1.l, c1.a, c1.b);
    let (l2, a2, b2) = (c2.l, c2.a, c2.b);

    let c1s = (a1 * a1 + b1 * b1).sqrt();
    let c2s = (a2 * a2 + b2 * b2).sqrt();
    let c_bar = (c1s + c2s) / 2.0;
    let c_bar7 = c_bar.powi(7);
    let g = 0.5 * (1.0 - (c_bar7 / (c_bar7 + 25f64.powi(7))).sqrt());

    let a1p = (1.0 + g) * a1;
    let a2p = (1.0 + g) * a2;

    let c1p = (a1p * a1p + b1 * b1).sqrt();
    let c2p = (a2p * a2p + b2 * b2).sqrt();

    let hp = |b: f64, a: f64| -> f64 {
        if b == 0.0 && a == 0.0 {
            0.0
        } else {
            let h = b.atan2(a).to_degrees();
            if h < 0.0 {
                h + 360.0
            } else {
                h
            }
        }
    };
    let h1p = hp(b1, a1p);
    let h2p = hp(b2, a2p);

    let dlp = l2 - l1;
    let dcp = c2p - c1p;

    let dhp = if c1p * c2p == 0.0 {
        0.0
    } else {
        let d = h2p - h1p;
        if d > 180.0 {
            d - 360.0
        } else if d < -180.0 {
            d + 360.0
        } else {
            d
        }
    };
    let d_hp = 2.0 * (c1p * c2p).sqrt() * (dhp.to_radians() / 2.0).sin();

    let lbp = (l1 + l2) / 2.0;
    let cbp = (c1p + c2p) / 2.0;

    let hbp = if c1p * c2p == 0.0 {
        h1p + h2p
    } else if (h1p - h2p).abs() <= 180.0 {
        (h1p + h2p) / 2.0
    } else if h1p + h2p < 360.0 {
        (h1p + h2p + 360.0) / 2.0
    } else {
        (h1p + h2p - 360.0) / 2.0
    };

    let t = 1.0 - 0.17 * (hbp - 30.0).to_radians().cos()
        + 0.24 * (2.0 * hbp).to_radians().cos()
        + 0.32 * (3.0 * hbp + 6.0).to_radians().cos()
        - 0.20 * (4.0 * hbp - 63.0).to_radians().cos();

    let d_theta = 30.0 * (-((hbp - 275.0) / 25.0).powi(2)).exp();
    let cbp7 = cbp.powi(7);
    let rc = 2.0 * (cbp7 / (cbp7 + 25f64.powi(7))).sqrt();
    let sl = 1.0 + 0.015 * (lbp - 50.0).powi(2) / (20.0 + (lbp - 50.0).powi(2)).sqrt();
    let sc = 1.0 + 0.045 * cbp;
    let sh = 1.0 + 0.015 * cbp * t;
    let rt = -(2.0 * d_theta).to_radians().sin() * rc;

    ((dlp / sl).powi(2) + (dcp / sc).powi(2) + (d_hp / sh).powi(2) + rt * (dcp / sc) * (d_hp / sh))
        .sqrt()
}
