        (false, true) => Color::from_lch(x, y, z, alpha),
        (true, false) => Color::from_oklab(x, y, z, alpha),
        (true, true) => Color::from_oklch(x, y, z, alpha),
    })
}

fn parse_named(input: &str) -> Option<Color> {
    let lower = input.to_ascii_lowercase();
    named::lookup(&lower)
}

/// Parse a color from the given string.
pub fn parse_color(input: &str) -> Option<Color> {
    let s = input.trim();
    parse_hex(s)
        .or_else(|| parse_rgb_function(s))
        .or_else(|| parse_rgb_bare(s))
