        .or_else(|| parse_hsl_like(s, "hsv(", "hsva(", true))
        .or_else(|| parse_gray(s))
        .or_else(|| parse_lab_like(s, "lab(", false, false))
        .or_else(|| parse_lab_like(s, "lch(", true, false))
        .or_else(|| parse_lab_like(s, "oklab(", false, true))
        .or_else(|| parse_lab_like(s, "oklch(", true, true))
        .or_else(|| parse_named(s))
}
