//! ANSI terminal escape sequences.

use crate::color::{Color, Lab};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Mode {
    Ansi8Bit,
    TrueColor,
}

fn palette_rgb(code: u8) -> (u8, u8, u8) {
    if code >= 232 {
        let v = 8 + 10 * (code - 232);
        (v, v, v)
    } else {
        let i = code - 16;
        let level = |c: u8| if c == 0 { 0 } else { 55 + 40 * c };
        (level(i / 36), level((i / 6) % 6), level(i % 6))
    }
}

fn palette_labs() -> &'static Vec<(u8, Lab)> {
    use std::sync::OnceLock;
    static LABS: OnceLock<Vec<(u8, Lab)>> = OnceLock::new();
    LABS.get_or_init(|| {
        (16u8..255)
            .map(|code| {
                let (r, g, b) = palette_rgb(code);
                (code, Color::from_rgb(r, g, b).to_lab())
            })
            .collect()
    })
}

/// Approximate the color by one of the 256 ANSI colors.
pub fn to_ansi_8bit(color: &Color) -> u8 {
    let lab = color.to_lab();
    palette_labs()
        .iter()
        .min_by_key(|(_, p)| crate::color::ciede2000(&lab, p) as i32)
        .map(|(code, _)| *code)
        .unwrap_or(16)
}

pub fn fg_code(color: &Color, mode: Mode) -> String {
    match mode {
        Mode::Ansi8Bit => format!("38;5;{}", to_ansi_8bit(color)),
        Mode::TrueColor => {
            let c = color.to_rgba();
            format!("38;2;{};{};{}", c.r, c.g, c.b)
        }
    }
}

pub fn bg_code(color: &Color, mode: Mode) -> String {
    match mode {
        Mode::Ansi8Bit => format!("48;5;{}", to_ansi_8bit(color)),
        Mode::TrueColor => {
            let c = color.to_rgba();
            format!("48;2;{};{};{}", c.r, c.g, c.b)
        }
    }
}

pub fn escape_sequence_fg(color: &Color, mode: Mode) -> String {
    format!("\x1b[{}m", fg_code(color, mode))
}

#[derive(Clone, Default)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub bold: bool,
    pub italic: bool,
    pub underline: bool,
}

impl Style {
    pub fn new() -> Style {
        Style::default()
    }

    pub fn foreground(mut self, c: &Color) -> Style {
        self.fg = Some(*c);
        self
    }

    pub fn on(mut self, c: &Color) -> Style {
        self.bg = Some(*c);
        self
    }

    pub fn bold(mut self, b: bool) -> Style {
        self.bold = b;
        self
    }

    pub fn italic(mut self, b: bool) -> Style {
        self.italic = b;
        self
    }

    pub fn underline(mut self, b: bool) -> Style {
        self.underline = b;
        self
    }

    pub fn escape_sequence(&self, mode: Mode) -> String {
        let mut codes: Vec<String> = vec![];
        if let Some(fg) = &self.fg {
            codes.push(fg_code(fg, mode));
        }
        if let Some(bg) = &self.bg {
            codes.push(bg_code(bg, mode));
        }
        if self.bold {
            codes.push("1".into());
        }
        if self.italic {
            codes.push("3".into());
        }
        if self.underline {
            codes.push("4".into());
        }
        format!("\x1b[{}m", codes.join(";"))
    }

    pub fn paint(&self, text: &str, mode: Option<Mode>) -> String {
        match mode {
            None => text.to_string(),
            Some(mode) => format!("{}{}\x1b[0m", self.escape_sequence(mode), text),
        }
    }
}
