//! A simple character canvas that uses "half block" characters to show
//! two pixels per terminal cell.

use std::io::{self, Write};

use crate::ansi::{Mode, Style};
use crate::color::Color;

pub struct Canvas {
    height: usize,
    width: usize,
    pixels: Vec<Option<Color>>,
    chars: Vec<Option<char>>,
}

impl Canvas {
    /// Create a new canvas. `height` is given in pixels (two pixels per row).
    pub fn new(height: usize, width: usize) -> Canvas {
        assert!(height % 2 == 0);
        Canvas {
            height,
            width,
            pixels: vec![None; height * width],
            chars: vec![None; height / 2 * width],
        }
    }

    pub fn draw_rect(&mut self, row: usize, col: usize, height: usize, width: usize, color: &Color) {
        for i in 0..height {
            for j in 0..width {
                if let Some(p) = self.pixel_mut(row + i, col + j) {
                    *p = Some(*color);
                }
            }
        }
    }

    pub fn draw_checkerboard(
        &mut self,
        row: usize,
        col: usize,
        height: usize,
        width: usize,
        dark: &Color,
        light: &Color,
    ) {
        for i in 0..height {
            for j in 0..width {
                let color = if (i + j) % 2 == 0 { light } else { dark };
                if let Some(p) = self.pixel_mut(row + i, col + j) {
                    *p = Some(*color);
                }
            }
        }
    }

    /// Draw text at the given text row (not pixel row).
    pub fn draw_text(&mut self, text_row: usize, col: usize, text: &str) {
        for (j, c) in text.chars().enumerate() {
            if col + j < self.width && text_row < self.height / 2 {
                self.chars[text_row * self.width + col + j] = Some(c);
            }
        }
    }

    fn pixel_mut(&mut self, row: usize, col: usize) -> Option<&mut Option<Color>> {
        if row < self.height && col < self.width {
            Some(&mut self.pixels[row * self.width + col])
        } else {
            None
        }
    }

    pub fn pixel(&self, row: usize, col: usize) -> Option<Color> {
        if row < self.height && col < self.width {
            self.pixels[row * self.width + col]
        } else {
            None
        }
    }

    pub fn render(&self, mode: Option<Mode>) -> String {
        let mut out = String::new();
        for i in 0..self.height / 2 {
            out.push_str("  ");
            for j in 0..self.width {
                if let Some(c) = self.chars[i * self.width + j] {
                    out.push(c);
                    continue;
                }
                let top = self.pixel(2 * i, j);
                let bottom = self.pixel(2 * i + 1, j);
                match (top, bottom) {
                    (Some(t), Some(b)) => {
                        let ch = if t == b { " " } else { "▀" };
                        out.push_str(&Style::new().foreground(&t).on(&b).paint(ch, mode));
                    }
                    (Some(t), None) => {
                        out.push_str(&Style::new().foreground(&t).paint("▀", mode));
                    }
                    (None, Some(b)) => {
                        out.push_str(&Style::new().foreground(&b).paint("▄", mode));
                    }
                    (None, None) => out.push(' '),
                }
            }
            out.push('\n');
        }
        out
    }

    pub fn print(&self, out: &mut dyn Write, mode: Option<Mode>) -> io::Result<()> {
        out.write_all(self.render(mode).as_bytes())
    }
}
