//! Generation of visually distinct colors via simulated annealing.

use std::io::Write;

use crate::color::{ciede2000, Color, Lab};
use crate::random::Rng;

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum DistanceMetric {
    CIE76,
    CIEDE2000,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Target {
    Mean,
    Min,
}

struct Params {
    initial_temperature: f64,
    cooling_rate: f64,
    num_iterations: usize,
    target: Target,
    mutation_radius: f64,
}

fn distance(metric: DistanceMetric, a: &Lab, b: &Lab) -> f64 {
    match metric {
        DistanceMetric::CIE76 => {
            ((a.l - b.l).powi(2) + (a.a - b.a).powi(2) + (a.b - b.b).powi(2)).sqrt()
        }
        DistanceMetric::CIEDE2000 => ciede2000(a, b),
    }
}

pub struct Annealing {
    pub colors: Vec<Color>,
    labs: Vec<Lab>,
    dist: Vec<Vec<f64>>,
    num_fixed: usize,
    metric: DistanceMetric,
}

impl Annealing {
    pub fn new(colors: Vec<Color>, num_fixed: usize, metric: DistanceMetric) -> Annealing {
        let labs: Vec<Lab> = colors.iter().map(|c| c.to_lab()).collect();
        let n = colors.len();
        let mut dist = vec![vec![0.0; n]; n];
        for i in 0..n {
            for j in 0..n {
                if i != j {
                    dist[i][j] = distance(metric, &labs[i], &labs[j]);
                }
            }
        }
        Annealing {
            colors,
            labs,
            dist,
            num_fixed,
            metric,
        }
    }

    /// For every free color, the distance to its nearest neighbor.
    fn nearest_distances(&self) -> Vec<f64> {
        let n = self.colors.len();
        (self.num_fixed..n)
            .map(|i| {
                (0..n)
                    .filter(|&j| j != i)
                    .map(|j| self.dist[i][j])
                    .fold(f64::INFINITY, f64::min)
            })
            .collect()
    }

    /// Returns (D_mean, D_min).
    pub fn statistics(&self) -> (f64, f64) {
        let nd = self.nearest_distances();
        let mean = nd.iter().sum::<f64>() / nd.len() as f64;
        let min = nd.iter().cloned().fold(f64::INFINITY, f64::min);
        (mean, min)
    }

    fn score(&self, target: Target) -> f64 {
        let (mean, min) = self.statistics();
        match target {
            Target::Mean => mean,
            Target::Min => min,
        }
    }

    fn set_color(&mut self, i: usize, c: Color) {
        self.colors[i] = c;
        self.labs[i] = c.to_lab();
        for j in 0..self.colors.len() {
            if j != i {
                let d = distance(self.metric, &self.labs[i], &self.labs[j]);
                self.dist[i][j] = d;
                self.dist[j][i] = d;
            }
        }
    }

    fn mutate(&self, rng: &mut Rng, c: &Color, radius: f64) -> Color {
        let rgb = c.to_rgba();
        let r = radius.max(1.0);
        let mut ch = |v: u8| -> u8 {
            let delta = rng.range_f64(-r, r);
            (v as f64 + delta).round().min(255.0).max(0.0) as u8
        };
        let nr = ch(rgb.r);
        let ng = ch(rgb.g);
        let nb = ch(rgb.b);
        Color::from_rgb(nr, ng, nb)
    }

    fn print_state(&self, out: &mut dyn Write, iter: usize, temperature: f64) {
        let (mean, min) = self.statistics();
        let mut line = format!(
            "[{:10}] D_mean = {:<6.2}; D_min = {:<6.2}; T = {:.6} ",
            iter, mean, min, temperature
        );
        for c in &self.colors {
            line.push_str(&c.to_hex_string(false));
            line.push(' ');
        }
        let _ = writeln!(out, "{}", line);
    }

    fn run(&mut self, rng: &mut Rng, params: &Params, verbose: bool, out: &mut dyn Write) {
        let n = self.colors.len();
        let mut temperature = params.initial_temperature;
        let mut score = self.score(params.target);

        for iter in 0..params.num_iterations {
            if iter > 0 && iter % 1000 == 0 {
                temperature *= params.cooling_rate;
            }

            let idx = self.num_fixed + rng.below(n - self.num_fixed);
            let old = self.colors[idx];
            let radius = params.mutation_radius * (temperature / params.initial_temperature).sqrt();
            let candidate = self.mutate(rng, &old, radius);
            self.set_color(idx, candidate);
            let new_score = self.score(params.target);

            let accept = new_score >= score || {
                let p = ((new_score - score) / temperature).exp();
                rng.next_f64() < p
            };

            if accept {
                score = new_score;
            } else {
                self.set_color(idx, old);
            }

            if verbose && iter % 5000 == 0 {
                self.print_state(out, iter, temperature);
            }
        }
    }

    /// Reorder the colors such that each next color is as different as
    /// possible from all colors that come before it.
    fn reorder(&mut self) {
        let n = self.colors.len();
        if n == 0 {
            return;
        }
        let mut order: Vec<usize> = vec![0];
        let mut remaining: Vec<usize> = (1..n).collect();
        while !remaining.is_empty() {
            let mut best_k = 0;
            let mut best_d = f64::NEG_INFINITY;
            for (k, &i) in remaining.iter().enumerate() {
                let d = order
                    .iter()
                    .map(|&j| self.dist[i][j])
                    .fold(f64::INFINITY, f64::min);
                if d > best_d {
                    best_d = d;
                    best_k = k;
                }
            }
            order.push(remaining.remove(best_k));
        }
        let colors: Vec<Color> = order.iter().map(|&i| self.colors[i]).collect();
        let labs: Vec<Lab> = order.iter().map(|&i| self.labs[i]).collect();
        let dist: Vec<Vec<f64>> = order
            .iter()
            .map(|&i| order.iter().map(|&j| self.dist[i][j]).collect())
            .collect();
        self.colors = colors;
        self.labs = labs;
        self.dist = dist;
    }

    fn print_matrix(&self, out: &mut dyn Write) {
        let n = self.colors.len();
        let mut s = String::from("\n\n        ");
        for c in &self.colors {
            s.push_str(&c.to_hex_string(false));
            s.push(' ');
        }
        s.push_str("\n\n");
        for i in 0..n {
            s.push_str(&self.colors[i].to_hex_string(false));
            s.push(' ');
            for j in 0..n {
                if i == j {
                    s.push_str("       ");
                } else {
                    s.push_str(&format!("{:7.2}", self.dist[i][j]));
                }
            }
            s.push_str(" \n");
        }
        s.push_str("\n\n");
        let _ = out.write_all(s.as_bytes());
    }
}

pub fn distinct_colors(
    count: usize,
    fixed: Vec<Color>,
    metric: DistanceMetric,
    verbose: bool,
) -> Vec<Color> {
    let mut rng = Rng::new();
    let num_fixed = fixed.len();
    let mut colors = fixed;
    while colors.len() < count {
        colors.push(Color::from_rgb(rng.next_u8(), rng.next_u8(), rng.next_u8()));
    }

    let mut annealing = Annealing::new(colors, num_fixed, metric);
    let stderr = std::io::stderr();
    let mut err = stderr.lock();

    let phase1 = Params {
        initial_temperature: 3.0,
        cooling_rate: 0.95,
        num_iterations: 100_000,
        target: Target::Mean,
        mutation_radius: 60.0,
    };
    annealing.run(&mut rng, &phase1, verbose, &mut err);

    let phase2 = Params {
        initial_temperature: 0.5,
        cooling_rate: 0.98,
        num_iterations: 200_000,
        target: Target::Min,
        mutation_radius: 12.0,
    };
    annealing.run(&mut rng, &phase2, verbose, &mut err);

    annealing.reorder();

    if verbose {
        annealing.print_matrix(&mut err);
    }

    annealing.colors
}
EOF
echo ok"}

