        Err(std::env::VarError::NotUnicode(v)) => Err(PastelError::UnknownColorMode(
            v.to_string_lossy().into_owned(),
        )),
        Err(std::env::VarError::NotPresent) => {
            let colorterm = std::env::var("COLORTERM").unwrap_or_default();
            if colorterm == "truecolor" || colorterm == "24bit" {
                Ok(Some(Mode::TrueColor))
            } else {
                Ok(Some(Mode::Ansi8Bit))
            }
        }
    }
}

fn colormode_is_truecolor_from_env() -> bool {
    if std::env::var("PASTEL_COLOR_MODE").is_ok() {
        return true;
    }
    let colorterm = std::env::var("COLORTERM").unwrap_or_default();
    colorterm == "truecolor" || colorterm == "24bit"
}

fn write_stderr(color: Color, title: &str, message: &str, mode: Option<Mode>) {
    let stderr = io::stderr();
