        .map(|s| s.as_str())
        .unwrap_or("auto");

    let colormode = if force_color {
        Some(Mode::TrueColor)
    } else {
        match mode_arg {
            "24bit" => Some(Mode::TrueColor),
            "8bit" => Some(Mode::Ansi8Bit),
            "off" => None,
