//! Output of colors to the terminal.

use std::io::Write;

use crate::ansi::Mode;
use crate::canvas::Canvas;
use crate::color::Color;
use crate::error::PastelError;
use crate::named::{named_colors, NamedColor};
use crate::Config;

pub struct Output<'a> {
    pub handle: &'a mut dyn Write,
    colors_shown: usize,
}

/// Returns named colors sorted by their (perceptual) distance to the given color,
/// with duplicates removed.
pub fn similar_colors(color: &Color) -> Vec<NamedColor> {
    let mut colors = named_colors();
    let distances: Vec<f64> = colors
        .iter()
        .map(|nc| color.distance_delta_e_ciede2000(&nc.color))
        .collect();
    let mut indexed: Vec<(f64, NamedColor)> = distances.into_iter().zip(colors.drain(..)).collect();
    indexed.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    let mut result: Vec<NamedColor> = indexed.into_iter().map(|(_, nc)| nc).collect();
    result.dedup_by(|a, b| a.color == b.color);
    result
}

pub fn exact_name(color: &Color) -> Option<&'static str> {
    named_colors()
        .into_iter()
        .find(|nc| nc.color == *color && color.alpha == 1.0)
        .map(|nc| nc.name)
}

impl<'a> Output<'a> {
    pub fn new(handle: &'a mut dyn Write) -> Output<'a> {
        Output {
            handle,
            colors_shown: 0,
        }
    }

    pub fn show_color_tty(&mut self, config: &Config, color: &Color) -> Result<(), PastelError> {
        let checkerboard_size: usize = 16;
        let color_panel_size: usize = 12;
