        args: &["--color-selection"],
        version_args: &["--version"],
    },
    ColorPickerTool {
        name: "yad",
        command: "yad",
        args: &["--color"],
        version_args: &["--version"],
    },
    ColorPickerTool {
        name: "hyprpicker",
        command: "hyprpicker",
        args: &[],
        version_args: &["--version"],
    },
    ColorPickerTool {
        name: "gdbus",
        command: "gdbus",
        args: &[
            "call",
            "--session",
            "--dest",
            "org.gnome.Shell.Screenshot",
            "--object-path",
            "/org/gnome/Shell/Screenshot",
            "--method",
            "org.gnome.Shell.Screenshot.PickColor",
        ],
        version_args: &["--version"],
    },
];

fn tool_available(tool: &ColorPickerTool) -> bool {
    Command::new(tool.command)
        .args(tool.version_args)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

fn parse_tool_output(tool: &ColorPickerTool, output: &str) -> Option<Color> {
    let output = output.trim();
    if tool.name == "gdbus" {
        // Output looks like: ({'color': <(0.1, 0.2, 0.3)>},)
        let start = output.find("<(")? + 2;
        let end = output[start..].find(")>")? + start;
        let parts: Vec<f64> = output[start..end]
            .split(',')
            .filter_map(|p| p.trim().parse::<f64>().ok())
            .collect();
        if parts.len() == 3 {
            return Some(Color::from_rgb_float(parts[0], parts[1], parts[2]));
        }
        return None;
    }
    if tool.name == "zenity" || tool.name == "yad" {
        if let Some(c) = parse_color(output) {
            return Some(c);
        }
    }
    parse_color(output)
}

pub fn run_external_colorpicker(picker: Option<&str>) -> Result<Color, PastelError> {
    for tool in TOOLS {
        if let Some(p) = picker {
            if !tool.name.eq_ignore_ascii_case(p) {
                continue;
            }
        }
        if !tool_available(tool) {
            continue;
        }
        let result = Command::new(tool.command)
            .args(tool.args)
            .stdin(Stdio::null())
            .stderr(Stdio::null())
            .output()
            .map_err(|_| PastelError::ColorPickerNotFound)?;
        let text = String::from_utf8(result.stdout).map_err(|_| PastelError::ColorInvalidUTF8)?;
        return parse_tool_output(tool, &text)
            .ok_or_else(|| PastelError::ColorParseError(text.trim().to_string()));
    }
    Err(PastelError::ColorPickerNotFound)
}

/// Print a spectrum of colors to standard error.
pub fn print_colorspectrum() -> Result<(), PastelError> {
    use std::io::{IsTerminal, Write};

    let mode: Option<Mode> = crate::colormode_from_env(std::io::stderr().is_terminal())?;

    let width = 48usize;
    let mut canvas = Canvas::new(width + 4, width + 2);
    canvas.draw_rect(2, 0, width + 2, width + 2, &Color::white());

    for y in 0..width {
        for x in 0..width {
            let rx = (x as f64) / (width as f64);
            let ry = (y as f64) / (width as f64);

            let h = 360.0 * rx;
            let s = 0.6;
            let l = 0.95 * ry;

            // Start with HSL, then normalize the lightness in LCh space.
            let color = Color::from_hsl(h, s, l);
            let mut lch = color.to_lch();
            lch.l = (lch.l + ry * 100.0) / 2.0;
            let color = Color::from_lch(lch.l, lch.c, lch.h, 1.0);

            canvas.draw_rect(3 + y, 1 + x, 1, 1, &color);
        }
    }

    let stderr = std::io::stderr();
    let mut handle = stderr.lock();
    canvas.print(&mut handle, mode)?;
    writeln!(handle)?;
    Ok(())
}
