            .ok_or_else(|| PastelError::ColorParseError(text.trim().to_string()));
    }
    Err(PastelError::ColorPickerNotFound)
}

/// Print a spectrum of colors to standard error.
pub fn print_colorspectrum() -> Result<(), PastelError> {
    use std::io::{IsTerminal, Write};

    let mode: Option<Mode> = crate::colormode_from_env(std::io::stderr().is_terminal())?;

    let width = 48usize;
    let mut canvas = Canvas::new(width + 4, width + 2);
    canvas.draw_rect(2, 0, width + 2, width + 2, &Color::white());

    for y in 0..width {
        for x in 0..width {
            let rx = (x as f64) / (width as f64);
            let ry = (y as f64) / (width as f64);

            let h = 360.0 * rx;
            let s = 0.6;
            let l = 0.95 * ry;

            // Start with HSL, then normalize the lightness in LCh space.
            let color = Color::from_hsl(h, s, l);
            let mut lch = color.to_lch();
            lch.l = (lch.l + ry * 100.0) / 2.0;
            let color = Color::from_lch(lch.l, lch.c, lch.h, 1.0);

            canvas.draw_rect(3 + y, 1 + x, 1, 1, &color);
        }
    }

    let stderr = std::io::stderr();
    let mut handle = stderr.lock();
    canvas.print(&mut handle, mode)?;
    writeln!(handle)?;
    Ok(())
}
