// ----------------------------------------------------------------------
// Mixing / interpolation

#[derive(Clone, Copy)]
pub enum ColorSpace {
    Lab,
    Lch,
    Rgb,
    Hsl,
    OkLab,
}

fn colorspace_from_str(s: &str) -> ColorSpace {
    match s.to_ascii_lowercase().as_str() {
        "lch" => ColorSpace::Lch,
        "rgb" => ColorSpace::Rgb,
        "hsl" => ColorSpace::Hsl,
        "oklab" => ColorSpace::OkLab,
        _ => ColorSpace::Lab,
    }
}

fn interpolate(a: f64, b: f64, f: f64) -> f64 {
    a + f * (b - a)
}

fn interpolate_angle(a: f64, b: f64, f: f64) -> f64 {
    let paths = [(a, b), (a, b + 360.0), (a + 360.0, b)];
    let shortest = paths
        .iter()
        .min_by(|p1, p2| {
            (p1.1 - p1.0)
                .abs()
                .partial_cmp(&(p2.1 - p2.0).abs())
                .unwrap_or(std::cmp::Ordering::Equal)
        })
        .unwrap();
    interpolate(shortest.0, shortest.1, f)
}

/// Mix `a` and `b`: f = 0 returns `a`, f = 1 returns `b`.
pub fn mix(a: &Color, b: &Color, space: ColorSpace, f: f64) -> Color {
    let alpha = interpolate(a.alpha, b.alpha, f);
    match space {
        ColorSpace::Rgb => {
            let ca = a.to_rgba_float();
            let cb = b.to_rgba_float();
            Color::from_rgba_float(
                interpolate(ca.r, cb.r, f),
                interpolate(ca.g, cb.g, f),
                interpolate(ca.b, cb.b, f),
                alpha,
            )
        }
        ColorSpace::Hsl => Color::from_hsla(
            interpolate_angle(a.hue, b.hue, f),
            interpolate(a.saturation, b.saturation, f),
            interpolate(a.lightness, b.lightness, f),
            alpha,
        ),
        ColorSpace::Lab => {
            let la = a.to_lab();
            let lb = b.to_lab();
            Color::from_lab(
                interpolate(la.l, lb.l, f),
                interpolate(la.a, lb.a, f),
                interpolate(la.b, lb.b, f),
                alpha,
            )
        }
        ColorSpace::Lch => {
            let la = a.to_lch();
            let lb = b.to_lch();
            Color::from_lch(
                interpolate(la.l, lb.l, f),
                interpolate(la.c, lb.c, f),
                interpolate_angle(la.h, lb.h, f),
                alpha,
            )
        }
        ColorSpace::OkLab => {
            let la = a.to_oklab();
            let lb = b.to_oklab();
            Color::from_oklab(
                interpolate(la.l, lb.l, f),
                interpolate(la.a, lb.a, f),
                interpolate(la.b, lb.b, f),
                alpha,
            )
        }
    }
}

fn cmd_mix(config: &Config, matches: &ArgMatches) -> Result<()> {
    let fraction = number_arg(matches, "fraction")?;
    let fraction = crate::color::clamp(0.0, 1.0, fraction);
    let space = colorspace_from_str(string_arg(matches, "colorspace"));
    let base = color_from_arg(config, string_arg(matches, "base"))?;
    for_each_color(config, matches, |out, color| {
        let mixed = mix(&color, &base, space, fraction);
        out.show_color(config, &mixed)
    })
}

fn cmd_gradient(config: &Config, matches: &ArgMatches) -> Result<()> {
    let count = count_arg(matches, "number")?;
    let space = colorspace_from_str(string_arg(matches, "colorspace"));

    let stops: Vec<String> = matches
        .get_many::<String>("color")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    if stops.len() < 2 {
        return Err(PastelError::GradientColorCountMustBeLargerThanOne);
    }
    if count < 2 {
        return Err(PastelError::GradientNumberMustBeLargerThanOne);
    }

    let mut colors = vec![];
    for s in &stops {
        colors.push(color_from_arg(config, s)?);
    }

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let mut out = Output::new(&mut handle);

    let num_segments = colors.len() - 1;
    for i in 0..count {
        let position = i as f64 / (count as f64 - 1.0);
        let scaled = position * num_segments as f64;
        let mut segment = scaled.floor() as usize;
        if segment >= num_segments {
            segment = num_segments - 1;
        }
        let local = scaled - segment as f64;
        let c = mix(&colors[segment], &colors[segment + 1], space, local);
        out.show_color(config, &c)?;
    }
    Ok(())
}

