// Formatting

fn format_color(color: &Color, format: &str) -> String {
    match format {
        "rgb" => color.to_rgb_string(),
        "rgb-float" => color.to_rgb_float_string(),
        "rgb-r" => format!("{}", color.to_rgba().r),
        "rgb-g" => format!("{}", color.to_rgba().g),
        "rgb-b" => format!("{}", color.to_rgba().b),
        "hex" => color.to_hex_string(true),
        "hsl" => color.to_hsl_string(true),
        "hsl-hue" => format!("{:.0}", color.hue),
        "hsl-saturation" => format!("{:.4}", color.saturation),
        "hsl-lightness" => format!("{:.4}", color.lightness),
        "hsv" => color.to_hsv_string(),
        "hsv-hue" => format!("{:.0}", color.to_hsva().h),
        "hsv-saturation" => format!("{:.4}", color.to_hsva().s),
        "hsv-value" => format!("{:.4}", color.to_hsva().v),
        "lch" => color.to_lch_string(),
        "lch-lightness" => format!("{:.2}", color.to_lch().l),
        "lch-chroma" => format!("{:.2}", color.to_lch().c),
        "lch-hue" => format!("{:.2}", color.to_lch().h),
        "oklch" => color.to_oklch_string(),
        "oklch-lightness" => format!("{:.4}", color.to_oklch().l),
        "oklch-chroma" => format!("{:.4}", color.to_oklch().c),
        "oklch-hue" => format!("{:.4}", color.to_oklch().h),
        "lab" => color.to_lab_string(),
        "lab-a" => format!("{:.2}", color.to_lab().a),
        "lab-b" => format!("{:.2}", color.to_lab().b),
        "oklab" => color.to_oklab_string(),
        "oklab-l" => format!("{:.4}", color.to_oklab().l),
        "oklab-a" => format!("{:.4}", color.to_oklab().a),
        "oklab-b" => format!("{:.4}", color.to_oklab().b),
        "luminance" => format!("{:.3}", color.luminance()),
        "brightness" => format!("{:.3}", color.brightness()),
        "ansi-8bit" => format!("\\x1b[38;5;{}m", ansi::to_ansi_8bit(color)),
        "ansi-24bit" => {
            let c = color.to_rgba();
            format!("\\x1b[38;2;{};{};{}m", c.r, c.g, c.b)
        }
        "ansi-8bit-value" => format!("{}", ansi::to_ansi_8bit(color)),
        "ansi-8bit-escapecode" => ansi::escape_sequence_fg(color, Mode::Ansi8Bit),
        "ansi-24bit-escapecode" => ansi::escape_sequence_fg(color, Mode::TrueColor),
        "cmyk" => color.to_cmyk_string(),
        "name" => similar_colors(color)
            .first()
            .map(|nc| nc.name.to_string())
            .unwrap_or_default(),
        _ => color.to_hex_string(true),
    }
}

fn cmd_format(config: &Config, matches: &ArgMatches) -> Result<()> {
    let format_type = string_arg(matches, "type").to_ascii_lowercase();
    for_each_color(config, matches, |out, color| {
        let text = format_color(&color, &format_type);
        if format_type.ends_with("-escapecode") {
            write!(out.handle, "{}", text)?;
        } else {
            let opaque = color.with_alpha(1.0);
            let style = Style::new().foreground(&opaque.text_color()).on(&opaque);
            writeln!(out.handle, "{}", style.paint(&text, config.colormode))?;
        }
        Ok(())
    })
}

// ----------------------------------------------------------------------

fn cmd_paint(config: &Config, matches: &ArgMatches) -> Result<()> {
    let fg = color_from_arg(config, string_arg(matches, "color"))?;
    let bg = match matches.get_one::<String>("on") {
        Some(s) => Some(color_from_arg(config, s)?),
        None => None,
    };

    let text = match matches.get_many::<String>("text") {
        Some(vals) => vals.cloned().collect::<Vec<String>>().join(" "),
        None => {
            let mut buffer = Vec::new();
            io::Read::read_to_end(&mut io::stdin(), &mut buffer)
                .map_err(|_| PastelError::CouldNotReadFromStdin)?;
            String::from_utf8_lossy(&buffer).into_owned()
        }
    };

    let mut style = Style::new().foreground(&fg);
    if let Some(bg) = &bg {
        style = style.on(bg);
    }
    style = style
        .bold(matches.get_flag("bold"))
        .italic(matches.get_flag("italic"))
        .underline(matches.get_flag("underline"));

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    write!(
        handle,
        "{}{}",
        style.paint(&text, config.colormode),
        if matches.get_flag("no-newline") { "" } else { "\n" }
    )?;
    Ok(())
}

// ----------------------------------------------------------------------
// Sorting

fn sort_key(color: &Color, order: &str) -> f64 {
    match order {
        "brightness" => color.brightness(),
        "luminance" => color.luminance(),
        "hue" => color.to_lch().h,
        "chroma" => color.to_lch().c,
        _ => 0.0,
    }
}

fn sort_colors(colors: &mut Vec<Color>, order: &str) {
    if order == "random" {
        let mut rng = Rng::new();
        rng.shuffle(colors);
        return;
    }
    let mut keyed: Vec<(f64, Color)> = colors.iter().map(|c| (sort_key(c, order), *c)).collect();
    keyed.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    *colors = keyed.into_iter().map(|(_, c)| c).collect();
}

fn cmd_list(config: &Config, matches: &ArgMatches) -> Result<()> {
    let order = string_arg(matches, "sort-order");
    let mut colors = named_colors();
    if order == "random" {
        let mut rng = Rng::new();
        rng.shuffle(&mut colors);
    } else {
        let mut keyed: Vec<(f64, crate::named::NamedColor)> = colors
            .drain(..)
            .map(|nc| (sort_key(&nc.color, order), nc))
            .collect();
        keyed.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
        colors = keyed.into_iter().map(|(_, nc)| nc).collect();
    }
    colors.dedup_by(|a, b| a.color == b.color);

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    for nc in colors {
        if config.interactive_mode {
            let style = Style::new()
                .foreground(&nc.color.text_color())
                .on(&nc.color);
            writeln!(
                handle,
                "{}",
                style.paint(&format!(" {:24}", nc.name), config.colormode)
            )?;
        } else {
            writeln!(handle, "{}", nc.name)?;
        }
    }
    Ok(())
}

fn cmd_sort(config: &Config, matches: &ArgMatches) -> Result<()> {
    let order = string_arg(matches, "sort-order").to_string();
    let mut colors = vec![];
    for c in ColorArgs::new(config, matches, "color")? {
        colors.push(c?);
    }
    sort_colors(&mut colors, &order);
    if matches.get_flag("reverse") {
        colors.reverse();
    }
    if matches.get_flag("unique") {
        colors.dedup_by(|a, b| {
            let ca = a.to_rgba();
            let cb = b.to_rgba();
            ca.r == cb.r && ca.g == cb.g && ca.b == cb.b
        });
    }

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let mut out = Output::new(&mut handle);
    for c in colors {
        out.show_color(config, &c)?;
    }
    Ok(())
}

// ----------------------------------------------------------------------

fn cmd_random(config: &Config, matches: &ArgMatches) -> Result<()> {
    let strategy = string_arg(matches, "strategy").to_string();
    let count = count_arg(matches, "number")?;
    let mut rng = Rng::new();

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let mut out = Output::new(&mut handle);
    for _ in 0..count {
        let color = match strategy.as_str() {
            "rgb" => Color::from_rgb(rng.next_u8(), rng.next_u8(), rng.next_u8()),
            "gray" => Color::graytone(rng.next_f64()),
            "lch_hue" => Color::from_lch(70.0, 35.0, rng.range_f64(0.0, 360.0), 1.0),
            _ => Color::from_hsl(
                rng.range_f64(0.0, 360.0),
                rng.range_f64(0.2, 0.8),
                rng.range_f64(0.3, 0.7),
            ),
        };
        out.show_color(config, &color)?;
    }
    Ok(())
}

fn cmd_distinct(config: &Config, matches: &ArgMatches) -> Result<()> {
    let count = count_arg(matches, "number")?;
    let metric = match string_arg(matches, "metric") {
        "CIEDE2000" => DistanceMetric::CIEDE2000,
        _ => DistanceMetric::CIE76,
    };
    let verbose = matches.get_flag("verbose");

    let mut fixed = vec![];
    if let Some(vals) = matches.get_many::<String>("color") {
        for v in vals {
            fixed.push(color_from_arg(config, v)?);
        }
    }

    if count < 2 {
        return Err(PastelError::DistinctColorCountMustBeLargerThanOne);
    }
    if fixed.len() >= count {
        return Err(PastelError::DistinctColorFixedColorsCannotBeMoreThanCount);
    }

    let colors = distinct_colors(count, fixed, metric, verbose);

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let mut out = Output::new(&mut handle);
    for c in colors {
        out.show_color(config, &c)?;
    }
    Ok(())
}

fn cmd_pick(config: &Config, matches: &ArgMatches) -> Result<()> {
    let count = count_arg(matches, "count")?;
    picker::print_colorspectrum()?;

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let mut out = Output::new(&mut handle);
    for _ in 0..count {
        let color = picker::run_external_colorpicker(config.colorpicker.as_deref())?;
        out.show_color(config, &color)?;
    }
    Ok(())
}

fn cmd_colorcheck() -> Result<()> {
    let stdout = io::stdout();
    let mut handle = stdout.lock();

    let colors = [
        Color::from_rgb(73, 39, 50),
        Color::from_rgb(16, 51, 30),
        Color::from_rgb(29, 54, 90),
    ];

    let make_canvas = || {
        let mut canvas = Canvas::new(12, 28);
        for (i, c) in colors.iter().enumerate() {
            canvas.draw_rect(2, 10 * i, 8, 8, c);
        }
        canvas
    };

    writeln!(handle)?;
    writeln!(handle, "8-bit mode:")?;
    make_canvas().print(&mut handle, Some(Mode::Ansi8Bit))?;
    writeln!(handle, "24-bit mode:")?;
    make_canvas().print(&mut handle, Some(Mode::TrueColor))?;
    writeln!(
        handle,
        "If your terminal emulator supports 24-bit colors, you should see three square color \
         panels in the lower row and the colors should look similar (but slightly different \
         from) the colors in the top row panels.\nThe panels in the lower row should look like \
         squares that are filled with a uniform color (no stripes or other artifacts).\n\n\
         You can also open https://github.com/sharkdp/pastel/blob/master/doc/colorcheck.md in \
         a browser to compare how the output should look like."
    )?;
    Ok(())
}
