//! Implementations of all subcommands.

use std::io::{self, BufRead, IsTerminal, Write};

use clap::ArgMatches;

use crate::ansi::{self, Mode, Style};
use crate::canvas::Canvas;
use crate::color::Color;
use crate::colorblind::{simulate, ColorblindnessType};
use crate::distinct::{distinct_colors, DistanceMetric};
use crate::error::PastelError;
use crate::named::named_colors;
use crate::output::{similar_colors, Output};
use crate::parser::parse_color;
use crate::picker;
use crate::random::Rng;
use crate::Config;

type Result<T> = std::result::Result<T, PastelError>;

fn number_arg(matches: &ArgMatches, name: &str) -> Result<f64> {
    let value = matches
        .get_one::<String>(name)
        .map(|s| s.as_str())
        .unwrap_or("");
    value
        .parse::<f64>()
        .map_err(|_| PastelError::CouldNotParseNumber(value.to_string()))
}

fn count_arg(matches: &ArgMatches, name: &str) -> Result<usize> {
    let value = matches
        .get_one::<String>(name)
        .map(|s| s.as_str())
        .unwrap_or("");
    value
        .parse::<usize>()
        .map_err(|_| PastelError::CouldNotParseNumber(value.to_string()))
}

fn string_arg<'a>(matches: &'a ArgMatches, name: &str) -> &'a str {
    matches
        .get_one::<String>(name)
        .map(|s| s.as_str())
        .unwrap_or("")
}

fn read_line_from_stdin() -> Result<Option<String>> {
    let stdin = io::stdin();
    let mut line = Vec::new();
    let n = stdin
        .lock()
        .read_until(b'\n', &mut line)
        .map_err(|_| PastelError::CouldNotReadFromStdin)?;
    if n == 0 {
        return Ok(None);
    }
    let s = String::from_utf8(line).map_err(|_| PastelError::ColorInvalidUTF8)?;
    Ok(Some(s))
}

pub fn color_from_arg(config: &Config, arg: &str) -> Result<Color> {
    if arg == "-" {
        let line = read_line_from_stdin()?.ok_or(PastelError::CouldNotReadFromStdin)?;
        let line = line.trim();
        return parse_color(line).ok_or_else(|| PastelError::ColorParseError(line.to_string()));
    }
    if arg == "pick" {
        picker::print_colorspectrum()?;
        return picker::run_external_colorpicker(config.colorpicker.as_deref());
    }
    parse_color(arg).ok_or_else(|| PastelError::ColorParseError(arg.to_string()))
}

/// Iterates over all color arguments (or lines from STDIN).
pub struct ColorArgs<'a> {
    config: &'a Config,
    args: Option<Vec<String>>,
    index: usize,
}

impl<'a> ColorArgs<'a> {
    pub fn new(config: &'a Config, matches: &ArgMatches, name: &str) -> Result<ColorArgs<'a>> {
        let args: Option<Vec<String>> = matches
            .get_many::<String>(name)
            .map(|vals| vals.cloned().collect());
        if args.is_none() && io::stdin().is_terminal() {
            return Err(PastelError::ColorArgRequired);
        }
        Ok(ColorArgs {
            config,
            args,
            index: 0,
        })
    }
}

impl<'a> Iterator for ColorArgs<'a> {
    type Item = Result<Color>;

    fn next(&mut self) -> Option<Result<Color>> {
        match &self.args {
            Some(args) => {
                if self.index >= args.len() {
                    return None;
                }
                let arg = args[self.index].clone();
                self.index += 1;
                Some(color_from_arg(self.config, &arg))
            }
            None => match read_line_from_stdin() {
                Ok(Some(line)) => {
                    let line = line.trim();
                    Some(
                        parse_color(line)
                            .ok_or_else(|| PastelError::ColorParseError(line.to_string())),
                    )
                }
                Ok(None) => None,
                Err(e) => Some(Err(e)),
            },
        }
    }
}

fn for_each_color<F>(config: &Config, matches: &ArgMatches, mut f: F) -> Result<()>
where
    F: FnMut(&mut Output, Color) -> Result<()>,
{
    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let mut out = Output::new(&mut handle);
    for color in ColorArgs::new(config, matches, "color")? {
        let color = color?;
        f(&mut out, color)?;
    }
    Ok(())
}

fn show_each<F>(config: &Config, matches: &ArgMatches, f: F) -> Result<()>
where
    F: Fn(&Color) -> Color,
{
    for_each_color(config, matches, |out, color| {
        let c = f(&color);
        out.show_color(config, &c)
    })
}

pub fn run_command(name: &str, matches: &ArgMatches, config: &Config) -> Result<()> {
    match name {
        "color" => show_each(config, matches, |c| *c),
        "saturate" => {
            let amount = number_arg(matches, "amount")?;
            show_each(config, matches, |c| c.saturate(amount))
        }
        "desaturate" => {
            let amount = number_arg(matches, "amount")?;
            show_each(config, matches, |c| c.desaturate(amount))
        }
        "lighten" => {
            let amount = number_arg(matches, "amount")?;
            show_each(config, matches, |c| c.lighten(amount))
        }
        "darken" => {
            let amount = number_arg(matches, "amount")?;
            show_each(config, matches, |c| c.darken(amount))
        }
        "rotate" => {
            let degrees = number_arg(matches, "degrees")?;
            show_each(config, matches, |c| c.rotate_hue(degrees))
        }
        "complement" => show_each(config, matches, |c| c.complementary()),
        "to-gray" => show_each(config, matches, |c| c.to_gray()),
        "textcolor" => show_each(config, matches, |c| c.text_color()),
        "gray" => {
            let lightness = number_arg(matches, "lightness")?;
            let stdout = io::stdout();
            let mut handle = stdout.lock();
            let mut out = Output::new(&mut handle);
            out.show_color(config, &Color::graytone(lightness))
        }
        "colorblind" => {
            let kind = match string_arg(matches, "type").to_ascii_lowercase().as_str() {
                "prot" => ColorblindnessType::Protanopia,
                "deuter" => ColorblindnessType::Deuteranopia,
                _ => ColorblindnessType::Tritanopia,
            };
            show_each(config, matches, |c| simulate(c, kind))
        }
        "set" => {
            let property = string_arg(matches, "property").to_ascii_lowercase();
            let value = number_arg(matches, "value")?;
            show_each(config, matches, |c| set_property(c, &property, value))
        }
        "mix" => cmd_mix(config, matches),
        "gradient" => cmd_gradient(config, matches),
        "format" => cmd_format(config, matches),
        "paint" => cmd_paint(config, matches),
        "list" => cmd_list(config, matches),
        "sort-by" => cmd_sort(config, matches),
        "random" => cmd_random(config, matches),
        "distinct" => cmd_distinct(config, matches),
        "pick" => cmd_pick(config, matches),
        "colorcheck" => cmd_colorcheck(),
        _ => unreachable!("unknown subcommand"),
    }
}

fn set_property(c: &Color, property: &str, value: f64) -> Color {
    match property {
        "red" | "green" | "blue" => {
            let rgba = c.to_rgba();
            let v = value as u8;
            let (r, g, b) = match property {
                "red" => (v, rgba.g, rgba.b),
                "green" => (rgba.r, v, rgba.b),
                _ => (rgba.r, rgba.g, v),
            };
            Color::from_rgba(r, g, b, c.alpha)
        }
        "hsl-hue" => Color::from_hsla(value, c.saturation, c.lightness, c.alpha),
        "hsl-saturation" => Color::from_hsla(c.hue, value, c.lightness, c.alpha),
        "hsl-lightness" => Color::from_hsla(c.hue, c.saturation, value, c.alpha),
        "lightness" => {
            let lch = c.to_lch();
            Color::from_lch(value, lch.c, lch.h, c.alpha)
        }
        "chroma" => {
            let lch = c.to_lch();
            Color::from_lch(lch.l, value, lch.h, c.alpha)
        }
        "hue" => {
            let lch = c.to_lch();
            Color::from_lch(lch.l, lch.c, value, c.alpha)
        }
        "lab-a" => {
            let lab = c.to_lab();
            Color::from_lab(lab.l, value, lab.b, c.alpha)
        }
        "lab-b" => {
            let lab = c.to_lab();
            Color::from_lab(lab.l, lab.a, value, c.alpha)
        }
        "oklab-l" => {
            let lab = c.to_oklab();
            Color::from_oklab(value, lab.a, lab.b, c.alpha)
        }
        "oklab-a" => {
            let lab = c.to_oklab();
            Color::from_oklab(lab.l, value, lab.b, c.alpha)
        }
        "oklab-b" => {
            let lab = c.to_oklab();
            Color::from_oklab(lab.l, lab.a, value, c.alpha)
        }
        "alpha" => c.with_alpha(value),
        _ => *c,
    }
}

// ----------------------------------------------------------------------
// Mixing / interpolation

#[derive(Clone, Copy)]
pub enum ColorSpace {
    Lab,
    Lch,
    Rgb,
    Hsl,
    OkLab,
}

fn colorspace_from_str(s: &str) -> ColorSpace {
    match s.to_ascii_lowercase().as_str() {
        "lch" => ColorSpace::Lch,
        "rgb" => ColorSpace::Rgb,
        "hsl" => ColorSpace::Hsl,
        "oklab" => ColorSpace::OkLab,
        _ => ColorSpace::Lab,
    }
}

fn interpolate(a: f64, b: f64, f: f64) -> f64 {
    a + f * (b - a)
}

fn interpolate_angle(a: f64, b: f64, f: f64) -> f64 {
    let paths = [(a, b), (a, b + 360.0), (a + 360.0, b)];
    let shortest = paths
        .iter()
        .min_by(|p1, p2| {
            (p1.1 - p1.0)
                .abs()
                .partial_cmp(&(p2.1 - p2.0).abs())
                .unwrap_or(std::cmp::Ordering::Equal)
        })
        .unwrap();
    interpolate(shortest.0, shortest.1, f)
}

/// Mix `a` and `b`: f = 0 returns `a`, f = 1 returns `b`.
pub fn mix(a: &Color, b: &Color, space: ColorSpace, f: f64) -> Color {
    let alpha = interpolate(a.alpha, b.alpha, f);
    match space {
        ColorSpace::Rgb => {
            let ca = a.to_rgba_float();
            let cb = b.to_rgba_float();
            Color::from_rgba_float(
                interpolate(ca.r, cb.r, f),
                interpolate(ca.g, cb.g, f),
                interpolate(ca.b, cb.b, f),
                alpha,
            )
        }
        ColorSpace::Hsl => Color::from_hsla(
            interpolate_angle(a.hue, b.hue, f),
            interpolate(a.saturation, b.saturation, f),
            interpolate(a.lightness, b.lightness, f),
            alpha,
        ),
        ColorSpace::Lab => {
            let la = a.to_lab();
            let lb = b.to_lab();
            Color::from_lab(
                interpolate(la.l, lb.l, f),
                interpolate(la.a, lb.a, f),
                interpolate(la.b, lb.b, f),
                alpha,
            )
        }
        ColorSpace::Lch => {
            let la = a.to_lch();
            let lb = b.to_lch();
            Color::from_lch(
                interpolate(la.l, lb.l, f),
                interpolate(la.c, lb.c, f),
                interpolate_angle(la.h, lb.h, f),
                alpha,
            )
        }
        ColorSpace::OkLab => {
            let la = a.to_oklab();
            let lb = b.to_oklab();
            Color::from_oklab(
                interpolate(la.l, lb.l, f),
                interpolate(la.a, lb.a, f),
                interpolate(la.b, lb.b, f),
                alpha,
            )
        }
    }
}

fn cmd_mix(config: &Config, matches: &ArgMatches) -> Result<()> {
    let fraction = number_arg(matches, "fraction")?;
    let fraction = crate::color::clamp(0.0, 1.0, fraction);
    let space = colorspace_from_str(string_arg(matches, "colorspace"));
    let base = color_from_arg(config, string_arg(matches, "base"))?;
    for_each_color(config, matches, |out, color| {
        let mixed = mix(&color, &base, space, fraction);
        out.show_color(config, &mixed)
    })
}

fn cmd_gradient(config: &Config, matches: &ArgMatches) -> Result<()> {
    let count = count_arg(matches, "number")?;
    let space = colorspace_from_str(string_arg(matches, "colorspace"));

    let stops: Vec<String> = matches
        .get_many::<String>("color")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    if stops.len() < 2 {
        return Err(PastelError::GradientColorCountMustBeLargerThanOne);
    }
    if count < 2 {
        return Err(PastelError::GradientNumberMustBeLargerThanOne);
    }

    let mut colors = vec![];
    for s in &stops {
        colors.push(color_from_arg(config, s)?);
    }

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let mut out = Output::new(&mut handle);

    let num_segments = colors.len() - 1;
    for i in 0..count {
        let position = i as f64 / (count as f64 - 1.0);
        let scaled = position * num_segments as f64;
        let mut segment = scaled.floor() as usize;
        if segment >= num_segments {
            segment = num_segments - 1;
        }
        let local = scaled - segment as f64;
        let c = mix(&colors[segment], &colors[segment + 1], space, local);
        out.show_color(config, &c)?;
    }
    Ok(())
}

// ----------------------------------------------------------------------
// Formatting

fn format_color(color: &Color, format: &str) -> String {
    match format {
        "rgb" => color.to_rgb_string(),
        "rgb-float" => color.to_rgb_float_string(),
        "rgb-r" => format!("{}", color.to_rgba().r),
        "rgb-g" => format!("{}", color.to_rgba().g),
        "rgb-b" => format!("{}", color.to_rgba().b),
        "hex" => color.to_hex_string(true),
        "hsl" => color.to_hsl_string(true),
        "hsl-hue" => format!("{:.0}", color.hue),
        "hsl-saturation" => format!("{:.4}", color.saturation),
        "hsl-lightness" => format!("{:.4}", color.lightness),
        "hsv" => color.to_hsv_string(),
        "hsv-hue" => format!("{:.0}", color.to_hsva().h),
        "hsv-saturation" => format!("{:.4}", color.to_hsva().s),
        "hsv-value" => format!("{:.4}", color.to_hsva().v),
        "lch" => color.to_lch_string(),
        "lch-lightness" => format!("{:.2}", color.to_lch().l),
        "lch-chroma" => format!("{:.2}", color.to_lch().c),
        "lch-hue" => format!("{:.2}", color.to_lch().h),
        "oklch" => color.to_oklch_string(),
        "oklch-lightness" => format!("{:.4}", color.to_oklch().l),
        "oklch-chroma" => format!("{:.4}", color.to_oklch().c),
        "oklch-hue" => format!("{:.4}", color.to_oklch().h),
        "lab" => color.to_lab_string(),
        "lab-a" => format!("{:.2}", color.to_lab().a),
        "lab-b" => format!("{:.2}", color.to_lab().b),
        "oklab" => color.to_oklab_string(),
        "oklab-l" => format!("{:.4}", color.to_oklab().l),
        "oklab-a" => format!("{:.4}", color.to_oklab().a),
        "oklab-b" => format!("{:.4}", color.to_oklab().b),
        "luminance" => format!("{:.3}", color.luminance()),
        "brightness" => format!("{:.3}", color.brightness()),
        "ansi-8bit" => format!("\\x1b[38;5;{}m", ansi::to_ansi_8bit(color)),
        "ansi-24bit" => {
            let c = color.to_rgba();
            format!("\\x1b[38;2;{};{};{}m", c.r, c.g, c.b)
        }
        "ansi-8bit-value" => format!("{}", ansi::to_ansi_8bit(color)),
        "ansi-8bit-escapecode" => ansi::escape_sequence_fg(color, Mode::Ansi8Bit),
        "ansi-24bit-escapecode" => ansi::escape_sequence_fg(color, Mode::TrueColor),
        "cmyk" => color.to_cmyk_string(),
        "name" => similar_colors(color)
            .first()
            .map(|nc| nc.name.to_string())
            .unwrap_or_default(),
        _ => color.to_hex_string(true),
    }
}

fn cmd_format(config: &Config, matches: &ArgMatches) -> Result<()> {
    let format_type = string_arg(matches, "type").to_ascii_lowercase();
    for_each_color(config, matches, |out, color| {
        let text = format_color(&color, &format_type);
        if format_type.ends_with("-escapecode") {
            write!(out.handle, "{}", text)?;
        } else {
            let opaque = color.with_alpha(1.0);
            let style = Style::new().foreground(&opaque.text_color()).on(&opaque);
            writeln!(out.handle, "{}", style.paint(&text, config.colormode))?;
        }
        Ok(())
    })
}

// ----------------------------------------------------------------------

fn cmd_paint(config: &Config, matches: &ArgMatches) -> Result<()> {
    let fg = color_from_arg(config, string_arg(matches, "color"))?;
    let bg = match matches.get_one::<String>("on") {
        Some(s) => Some(color_from_arg(config, s)?),
        None => None,
    };

    let text = match matches.get_many::<String>("text") {
        Some(vals) => vals.cloned().collect::<Vec<String>>().join(" "),
        None => {
            let mut buffer = Vec::new();
            io::Read::read_to_end(&mut io::stdin(), &mut buffer)
                .map_err(|_| PastelError::CouldNotReadFromStdin)?;
            String::from_utf8_lossy(&buffer).into_owned()
        }
    };

    let mut style = Style::new().foreground(&fg);
    if let Some(bg) = &bg {
        style = style.on(bg);
    }
    style = style
        .bold(matches.get_flag("bold"))
        .italic(matches.get_flag("italic"))
        .underline(matches.get_flag("underline"));

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    write!(
        handle,
        "{}{}",
        style.paint(&text, config.colormode),
        if matches.get_flag("no-newline") { "" } else { "\n" }
    )?;
    Ok(())
}

// ----------------------------------------------------------------------
// Sorting

fn sort_key(color: &Color, order: &str) -> f64 {
    match order {
        "brightness" => color.brightness(),
        "luminance" => color.luminance(),
        "hue" => color.to_lch().h,
        "chroma" => color.to_lch().c,
        _ => 0.0,
    }
}

fn sort_colors(colors: &mut Vec<Color>, order: &str) {
    if order == "random" {
        let mut rng = Rng::new();
        rng.shuffle(colors);
        return;
    }
    let mut keyed: Vec<(f64, Color)> = colors.iter().map(|c| (sort_key(c, order), *c)).collect();
    keyed.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    *colors = keyed.into_iter().map(|(_, c)| c).collect();
}

fn cmd_list(config: &Config, matches: &ArgMatches) -> Result<()> {
    let order = string_arg(matches, "sort-order");
    let mut colors = named_colors();
    if order == "random" {
        let mut rng = Rng::new();
        rng.shuffle(&mut colors);
    } else {
        let mut keyed: Vec<(f64, crate::named::NamedColor)> = colors
            .drain(..)
            .map(|nc| (sort_key(&nc.color, order), nc))
            .collect();
        keyed.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
        colors = keyed.into_iter().map(|(_, nc)| nc).collect();
    }
    colors.dedup_by(|a, b| a.color == b.color);

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    for nc in colors {
        if config.interactive_mode {
            let style = Style::new()
                .foreground(&nc.color.text_color())
                .on(&nc.color);
            writeln!(
                handle,
                "{}",
                style.paint(&format!(" {:24}", nc.name), config.colormode)
            )?;
        } else {
            writeln!(handle, "{}", nc.name)?;
        }
    }
    Ok(())
}

fn cmd_sort(config: &Config, matches: &ArgMatches) -> Result<()> {
    let order = string_arg(matches, "sort-order").to_string();
    let mut colors = vec![];
    for c in ColorArgs::new(config, matches, "color")? {
        colors.push(c?);
    }
    sort_colors(&mut colors, &order);
    if matches.get_flag("reverse") {
        colors.reverse();
    }
    if matches.get_flag("unique") {
        colors.dedup_by(|a, b| {
            let ca = a.to_rgba();
            let cb = b.to_rgba();
            ca.r == cb.r && ca.g == cb.g && ca.b == cb.b
        });
    }

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let mut out = Output::new(&mut handle);
    for c in colors {
        out.show_color(config, &c)?;
    }
    Ok(())
}

// ----------------------------------------------------------------------

fn cmd_random(config: &Config, matches: &ArgMatches) -> Result<()> {
    let strategy = string_arg(matches, "strategy").to_string();
    let count = count_arg(matches, "number")?;
    let mut rng = Rng::new();

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let mut out = Output::new(&mut handle);
    for _ in 0..count {
        let color = match strategy.as_str() {
            "rgb" => Color::from_rgb(rng.next_u8(), rng.next_u8(), rng.next_u8()),
            "gray" => Color::graytone(rng.next_f64()),
            "lch_hue" => Color::from_lch(70.0, 35.0, rng.range_f64(0.0, 360.0), 1.0),
            _ => Color::from_hsl(
                rng.range_f64(0.0, 360.0),
                rng.range_f64(0.2, 0.8),
                rng.range_f64(0.3, 0.7),
            ),
        };
        out.show_color(config, &color)?;
    }
    Ok(())
}

fn cmd_distinct(config: &Config, matches: &ArgMatches) -> Result<()> {
    let count = count_arg(matches, "number")?;
    let metric = match string_arg(matches, "metric") {
        "CIEDE2000" => DistanceMetric::CIEDE2000,
        _ => DistanceMetric::CIE76,
    };
    let verbose = matches.get_flag("verbose");

    let mut fixed = vec![];
    if let Some(vals) = matches.get_many::<String>("color") {
        for v in vals {
            fixed.push(color_from_arg(config, v)?);
        }
    }

    if count < 2 {
        return Err(PastelError::DistinctColorCountMustBeLargerThanOne);
    }
    if fixed.len() >= count {
        return Err(PastelError::DistinctColorFixedColorsCannotBeMoreThanCount);
    }

    let colors = distinct_colors(count, fixed, metric, verbose);

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let mut out = Output::new(&mut handle);
    for c in colors {
        out.show_color(config, &c)?;
    }
    Ok(())
}

fn cmd_pick(config: &Config, matches: &ArgMatches) -> Result<()> {
    let count = count_arg(matches, "count")?;
    picker::print_colorspectrum()?;

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let mut out = Output::new(&mut handle);
    for _ in 0..count {
        let color = picker::run_external_colorpicker(config.colorpicker.as_deref())?;
        out.show_color(config, &color)?;
    }
    Ok(())
}

fn cmd_colorcheck() -> Result<()> {
    let stdout = io::stdout();
    let mut handle = stdout.lock();

    let colors = [
        Color::from_rgb(73, 39, 50),
        Color::from_rgb(16, 51, 30),
        Color::from_rgb(29, 54, 90),
    ];

    let make_canvas = || {
        let mut canvas = Canvas::new(12, 28);
        for (i, c) in colors.iter().enumerate() {
            canvas.draw_rect(2, 10 * i, 8, 8, c);
        }
        canvas
    };

    writeln!(handle)?;
    writeln!(handle, "8-bit mode:")?;
    make_canvas().print(&mut handle, Some(Mode::Ansi8Bit))?;
    writeln!(handle, "24-bit mode:")?;
    make_canvas().print(&mut handle, Some(Mode::TrueColor))?;
    writeln!(
        handle,
        "If your terminal emulator supports 24-bit colors, you should see three square color \
         panels in the lower row and the colors should look similar (but slightly different \
         from) the colors in the top row panels.\nThe panels in the lower row should look like \
         squares that are filled with a uniform color (no stripes or other artifacts).\n\n\
         You can also open https://github.com/sharkdp/pastel/blob/master/doc/colorcheck.md in \
         a browser to compare how the output should look like."
    )?;
    Ok(())
}
