        for l in BufReader::new(f).lines(){ v.push(l.unwrap()); }
    }
    v
}
fn main(){
    let exp=load("hsl-hue");
    let mut stats=std::collections::BTreeMap::new();
    let mut ties=0; let mut tie_ok=0;
    for idx in 0..(1usize<<24) {
        let (ri,gi,bi)=((idx>>16) as i64,((idx>>8)&255) as i64,(idx&255) as i64);
        let (r,g,b)=(ri as f64/255.0,gi as f64/255.0,bi as f64/255.0);
        let max=r.max(g).max(b); let min=r.min(g).min(b); let c=max-min;
        if c==0.0 {continue}
        let (case,h)= if max==r {(0,60.0*((g-b)/c))} else if max==g {(1,60.0*((b-r)/c)+120.0)} else {(2,60.0*((r-g)/c)+240.0)};
        let h = if h<0.0 {h+360.0} else {h};
        // exact hue as rational: is it a tie?
        let mx=ri.max(gi).max(bi); let mn=ri.min(gi).min(bi); let cc=mx-mn;
        let num = if max==r {60*(gi-bi)} else if max==g {60*(bi-ri)+120*cc} else {60*(ri-gi)+240*cc};
        let num = if num<0 {num+360*cc} else {num};
        // tie if 2*num/cc is odd integer
        let is_tie = (2*num) % cc == 0 && ((2*num)/cc) % 2 == 1;
        if is_tie {
            ties+=1;
            let e:i64=exp[idx].parse().unwrap();
            let lower=(num*2/cc -1)/2;
            let up = e > lower;
            let key=(case, if h*2.0 < (2*num/cc) as f64 {"below"} else if h*2.0 > (2*num/cc) as f64 {"above"} else {"exact"}, if up {"up"} else {"down"}, lower%2==0);
            *stats.entry(key).or_insert(0)+=1;
            let mine=format!("{:.0}",h);
            if mine==exp[idx] {tie_ok+=1;}
        } else {
            if format!("{:.0}",h)!=exp[idx] { println!("NONTIE mismatch {} {} {}",ri,gi,bi); }
        }
    }
    println!("ties={} ok={}",ties,tie_ok);
    for (k,v) in stats { println!("{:?} {}",k,v); }
}
